import java.io.IOException;
import java.nio.channels.Channels;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.SecureDirectoryStream;
import java.nio.file.StandardOpenOption;
import java.util.Arrays;
import java.util.Base64;
import java.util.Set;

public class ProcMembershipProbe {
    public static void main(String[] args) throws IOException {
        Path fixtures = Path.of(args[0]);
        for (String name : Files.readAllLines(fixtures.resolve("cases.txt"))) {
            Path processDirectory = fixtures.resolve(name);
            byte[] expected = Files.readAllBytes(processDirectory.resolve("expected"));
            try (var directory = Files.newDirectoryStream(processDirectory)) {
                if (directory instanceof SecureDirectoryStream<Path> secure) {
                    try (var channel = secure.newByteChannel(Path.of("cgroup"), Set.of(StandardOpenOption.READ));
                         var input = Channels.newInputStream(channel)) {
                        byte[] observed = input.readAllBytes();
                        System.out.println(name + " expected=" + Base64.getEncoder().encodeToString(expected)
                            + " observed=" + Base64.getEncoder().encodeToString(observed)
                            + " equal=" + Arrays.equals(expected, observed));
                    }
                } else {
                    throw new UnsupportedOperationException("Provider exposes no secure directory stream");
                }
            } catch (IOException failure) {
                System.out.println(name + " unavailable=" + failure.getClass().getName());
            }
        }

        Path self = Path.of(args[1]).resolve(Long.toString(ProcessHandle.current().pid()));
        byte[] reference = Files.readAllBytes(self.resolve("cgroup"));
        try (var directory = Files.newDirectoryStream(self)) {
            if (directory instanceof SecureDirectoryStream<Path> secure) {
                try (var channel = secure.newByteChannel(Path.of("cgroup"), Set.of(StandardOpenOption.READ));
                     var input = Channels.newInputStream(channel)) {
                    byte[] observed = input.readAllBytes();
                    System.out.println("self reference=" + Base64.getEncoder().encodeToString(reference)
                        + " observed=" + Base64.getEncoder().encodeToString(observed)
                        + " equal=" + Arrays.equals(reference, observed));
                }
            } else {
                throw new UnsupportedOperationException("Provider exposes no secure directory stream");
            }
        }
    }
}

