import java.nio.file.Path;
import com.holdmyspot.codexunleashed.scheduler.LinuxResidency;
public class SamplerProbe {
    public static void main(String[] args) throws java.io.IOException {
        var sample = LinuxResidency.read(Path.of(args[0]), Path.of(args[1]), Path.of(args[2]));
        System.out.println("residentBytes=" + sample.residentBytes() + " processes=" + sample.processes());
    }
}

